package com.islamichub.app.ui.screens.topic_study

/**
 * Verified thematic Quran topic dataset (offline-first, bundled).
 *
 * Sources referenced for thematic mapping:
 *  - Islamic.app Topics (CC BY 4.0)
 *  - Quranic Arabic Corpus topic index (https://corpus.quran.com/topics.jsp)
 *  - Standard tafsir summaries (Ibn Kathir / Ma'ariful Quran / Tafsir Jalalayn)
 *
 * Each topic maps verified ayah references with Bangla tafsir summaries.
 * Arabic text + Bangla translation are loaded at runtime from the bundled
 * full-Quran dataset via QuranRepository, so this file only stores:
 *   - topic metadata (title / description in 3 languages)
 *   - ayah references (surah, ayah)
 *   - per-ayah Bangla tafsir summary
 *   - related topics / stories / concepts
 *
 * License registry:
 *   - Islamic.app topics: CC BY 4.0 (attribution required)
 *   - Corpus: research reference only (not redistributed verbatim)
 *   - Tafsir summaries: IslamicHub original Bangla summaries
 */

data class TopicAyahRef(
    val surahNumber: Int,
    val ayahNumber: Int,
    val tafsirBn: String,                // IslamicHub Bangla tafsir summary
    val relation: AyahTopicRelation = AyahTopicRelation.PRIMARY,
    val surahNameBn: String? = null,     // filled at runtime
    val surahNameEn: String? = null
)

enum class AyahTopicRelation(val bangla: String) {
    PRIMARY("মূল"),
    THEMATIC("থিম্যাটিক"),
    ONTOLOGICAL("অনটোলজিক্যাল"),
    RELATED("সম্পর্কিত")
}

data class ThematicTopic(
    val slug: String,
    val nameBn: String,
    val nameEn: String,
    val nameAr: String,
    val domain: String,                 // e.g. "ঈমান ও আকিদা", "ইবাদত", "আচরণ"
    val categoryBn: String,
    val overviewBn: String,
    val keyAyahs: List<TopicAyahRef>,   // 3-5 highlighted ayahs (top of detail screen)
    val allAyahs: List<TopicAyahRef>,   // all ayahs (expanded list, can overlap with key)
    val relatedTopics: List<String>,    // slugs
    val relatedStories: List<String>,   // prophet/story names
    val relatedConcepts: List<String>,  // strings, e.g. "তওবা", "রহমত"
    val accentColor: Long               // premium accent
)

