            keyAyahs = listOf(
                TopicAyahRef(14, 7, "তোমাদের রব ঘোষণা করেছেন: তোমরা যদি শুকরিয়া আদায় করো আমি তোমাদের নিয়ামত বাড়িয়ে দেব। আর যদি অকৃতজ্ঞ হও তবে আমার শাস্তি কঠিন।"),
                TopicAyahRef(2, 152, "অতএব তোমরা আমাকে স্মরণ করো, আমিও তোমাদের স্মরণ করবো। তোমরা আমার কৃতজ্ঞ হও এবং অকৃতজ্ঞ হয়ো না।"),
                TopicAyahRef(39, 7, "তোমরা আল্লাহর কৃতজ্ঞ হলে তিনি তা গ্রহণ করেন। তিনি তোমাদের অর্থ কখনো প্রয়োজন করেন না। আল্লাহ তাঁর বান্দাদের প্রতি দয়ালু।")
            ),
            allAyahs = listOf(
                TopicAyahRef(2, 152, "আমাকে স্মরণ করো, আমিও তোমাদের স্মরণ করবো। শুকরিয়া আদায় করো, অকৃতজ্ঞ হয়ো না।"),
                TopicAyahRef(2, 172, "হে ঈমানদারগণ! আমি তোমাদেরকে যে পবিত্র বস্তু দিয়েছি তা থেকে খাও এবং আল্লাহর শুকরিয়া আদায় করো।"),
                TopicAyahRef(3, 144, "মুহাম্মদ সা. শুধু একজন রাসূল। তাঁর পূর্বে অনেক রাসূল অতিবাহিত হয়েছেন। তিনি মারা গেলে কি তোমরা পিছিয়ে যাবে?"),
                TopicAyahRef(4, 147, "আল্লাহ তোমাদের শুকরিয়া ও ঈমানের কোনো প্রয়োজন করেন না যদি তোমরা শুকরিয়া আদায় করো ও ঈমান আনো।"),
                TopicAyahRef(5, 6, "আল্লাহ তোমাদের কোনো কষ্ট দিতে চান না, বরং তিনি তোমাদের পবিত্র করতে চান এবং তোমাদের নিয়ামত পূর্ণ করতে চান যাতে তোমরা শুকরিয়া আদায় করো।"),
                TopicAyahRef(7, 10, "আমি তোমাদেরকে পৃথিবীতে প্রতিষ্ঠিত করেছি এবং তোমাদের জন্য জীবনোপকরণ দান করেছি। তোমরা কম শুকরিয়া আদায় করো।"),
                TopicAyahRef(7, 58, "পবিত্র ভূমি তার উদ্ভিদ উৎপন্ন করে তার রবের ইচ্ছায়। যে ভূমি পঙ্কিল তা সামান্যই উৎপন্ন করে। এভাবেই আমি শুকরিয়া আদায়কারী সম্প্রদায়ের জন্য আয়াতসমূহ বিশদভাবে বর্ণনা করি।"),
                TopicAyahRef(10, 9, "যারা ঈমান এনেছে ও সৎকর্ম করেছে, তাদেরকে তাদের রব ঈমানের কারণে হেদায়েত করবেন। সম্মানিত জান্নাতে তাদের অবস্থান নিচে নহর প্রবাহিত।"),
                TopicAyahRef(12, 38, "ইউসুফ বললেন: এটা আমাকে আমার রব শিখিয়েছেন। আমি তাঁর সাথে শিরক করি না, যিনি আমাকে ইব্রাহিম, ইসহাক ও ইয়াকুবের ধর্মে প্রতিষ্ঠিত করেছেন।"),
                TopicAyahRef(14, 7, "তোমরা শুকরিয়া আদায় করলে আমি নিয়ামত বাড়িয়ে দেব। অকৃতজ্ঞ হলে শাস্তি কঠিন।"),
                TopicAyahRef(16, 14, "তিনিই সমুদ্র থেকে তোমাদের জন্য তাজা মাছ আনেন। যাতে তোমরা তা থেকে খেতে পারো এবং অলংকার পরিধান করো। আল্লাহর শুকরিয়া আদায় করো।"),
                TopicAyahRef(16, 18, "তোমরা আল্লাহর নিয়ামত গণনা করলে তা শেষ করতে পারবে না। আল্লাহ ক্ষমাশীল, করুণাময়।"),
                TopicAyahRef(16, 78, "আল্লাহ তোমাদের মাতৃগর্ভ থেকে বের করেছেন যখন তোমরা কিছুই জানতে না। তিনি তোমাদের কান, চোখ ও অন্তর দিয়েছেন যাতে তোমরা শুকরিয়া আদায় করো।"),
                TopicAyahRef(17, 3, "হে নূহের সন্তান! আমি তোমাদের নূহকে বানিয়েছিলাম আমার সত্য বান্দা। আমি তোমাদের নৌকায় আরোহণ করিয়েছিলাম। শুকরিয়া আদায় করো।"),
                TopicAyahRef(21, 80, "আমি দাউদকে শিখিয়েছিলাম বর্ম তৈরি যাতে তোমরা যুদ্ধে সুরক্ষিত থাকো। তোমরা কি শুকরিয়া আদায় করো?"),
                TopicAyahRef(23, 78, "তিনিই তোমাদের জন্য কান, চোখ ও অন্তর সৃষ্টি করেছেন। তোমরা খুব কমই শুকরিয়া আদায় করো।"),
                TopicAyahRef(27, 19, "সুলাইমান বললেন: হে আমার রব! আমাকে শক্তি দিয়েছেন এবং আমার পিতা-মাতাকে নিয়ামত দিয়েছেন। আমি তোমার শুকরিয়া আদায় করি।"),
                TopicAyahRef(27, 40, "যার কাছে জ্ঞান ছিল সে বলল: আমি এটা আনতে পারি। যখন সুলাইমান দেখলেন সিংহাসন তাঁর সামনে স্থাপিত, বললেন: এটা আমার রবের অনুগ্রহ।"),
                TopicAyahRef(30, 46, "তাঁর নিদর্শনসমূহের মধ্যে একটি হলো তিনি বায়ু প্রেরণ করেন সুসংবাদ বহনকারী। যাতে তিনি তোমাদের তাঁর রহমত আস্বাদন করান এবং জাহাজ তাঁর আদেশে চলে।"),
                TopicAyahRef(31, 12, "আমি লুকমানকে জ্ঞান দান করেছিলাম। তুমি আল্লাহর শুকরিয়া আদায় করো। যে শুকরিয়া আদায় করে সে নিজেরই কল্যাণ করে।"),
                TopicAyahRef(31, 14, "আমি মানুষকে তার পিতা-মাতার সাথে সদ্ব্যবহার করতে নির্দেশ দিয়েছি। তার মাতা দুর্বলতার উপর দুর্বলতা নিয়ে তাকে গর্ভে ধারণ করে।"),
                TopicAyahRef(32, 9, "তিনি তাকে সুবিন্যস্ত করেছেন ও তাতে তাঁর রূহ থেকে ফুঁকে দিয়েছেন। তিনি তোমাদের কান, চোখ ও অন্তর দিয়েছেন। তোমরা খুব কমই শুকরিয়া আদায় করো।"),
                TopicAyahRef(34, 13, "তারা সুলাইমানের জন্য যা ইচ্ছা তৈরি করতো — কিল্লা, মূর্তি, পাত্র যেমন বড় পাত্র। হে দাউদের পরিবার! শুকরিয়া আদায় করো।"),
                TopicAyahRef(34, 15, "সাবার বাসস্থানে একটি নিদর্শন ছিল — দুটি উদ্যান ডান ও বামে। তোমাদের রবের রিযিক খাও এবং শুকরিয়া আদায় করো। উত্তম নগরী ও ক্ষমাশীল রব।"),
                TopicAyahRef(35, 30, "যাতে তিনি তাদের পুরস্কার পূর্ণ করেন এবং তাদের অতিরিক্ত দান করেন। তিনি ক্ষমাশীল, কৃতজ্ঞতা স্বীকারকারী।"),
                TopicAyahRef(35, 34, "যারা ঈমান এনেছে ও সৎকর্ম করেছে তাদেরকে জান্নাতে প্রবেশ করানো হবে। সেখানে তাদের জন্য রয়েছে চিরস্থায়ী নিয়ামত।"),
                TopicAyahRef(36, 33, "মৃত ভূমি তাদের জন্য একটি নিদর্শন। আমি তাতে জীবন দান করি এবং তা থেকে শস্য উৎপন্ন করি যা তারা খায়।"),
                TopicAyahRef(36, 35, "যাতে তারা তার ফল থেকে খেতে পারে এবং তা তাদের হস্ত দ্বারা উৎপন্ন নয়। তারা কি শুকরিয়া আদায় করবে না?"),
                TopicAyahRef(36, 73, "তাদের জন্য এতে রয়েছে অনেক উপকার ও পানীয়। তবুও তারা কি শুকরিয়া আদায় করবে না?"),
                TopicAyahRef(39, 7, "তোমরা আল্লাহর শুকরিয়া আদায় করলে তিনি তা গ্রহণ করেন। আল্লাহ তাঁর বান্দাদের প্রতি দয়ালু।"),
                TopicAyahRef(39, 74, "তারা বলবে: আমাদের রবের প্রশংসা! তিনি আমাদের প্রতিশ্রুতি পূরণ করেছেন এবং আমাদের এই জমির অধিকারী করেছেন।"),
                TopicAyahRef(40, 61, "আল্লাহ তোমাদের জন্য রাত সৃষ্টি করেছেন যাতে তোমরা তাতে বিশ্রাম নাও এবং দিন দেখার জন্য। নিশ্চয় আল্লাহ মানুষের প্রতি অনুগ্রহকারী, কিন্তু তাদের অধিকাংশ শুকরিয়া আদায় করে না।"),
                TopicAyahRef(42, 48, "তারা মুখ ফিরিয়ে নিলে আমি তোমাকে তাদের উপর রক্ষক করে পাঠাইনি। তোমার দায়িত্ব কেবল পৌঁছে দেওয়া। আমি মানুষকে যখন রহমত স্বাদন করাই, তখন সে আনন্দিত হয়।"),
                TopicAyahRef(45, 13, "তিনি আসমান ও পৃথিবীতে যা কিছু সৃষ্টি করেছেন তা তোমাদের অধীন করেছেন। নিশ্চয় এতে চিন্তাশীল সম্প্রদায়ের জন্য নিদর্শন রয়েছে।"),
                TopicAyahRef(46, 15, "আমি মানুষকে পিতা-মাতার সাথে সদ্ব্যবহার করতে নির্দেশ দিয়েছি। তার মাতা কষ্টের সাথে তাকে গর্ভে ধারণ করে ও কষ্টে প্রসব করে।"),
                TopicAyahRef(52, 18, "তারা তাদের রব তাদেরকে যা দিয়েছেন তা স্বাদন করছে। তাদের রব তাদেরকে জাহান্নামের শাস্তি থেকে রক্ষা করেছেন।"),
                TopicAyahRef(54, 35, "এটি আমার নিদর্শন থেকে একটি নিদর্শন। আমি কি অধিকাংশকে শুকরিয়া আদায়কারী বানাই?"),
                TopicAyahRef(55, 13, "তোমরা কোন্ নিয়ামতকে অস্বীকার করবে তোমাদের রবের?"),
                TopicAyahRef(67, 23, "বলুন: তিনিই তোমাদের সৃষ্টি করেছেন এবং তোমাদের কান, চোখ ও অন্তর দিয়েছেন। তোমরা খুব কমই শুকরিয়া আদায় করো।"),
                TopicAyahRef(76, 9, "আমরা তোমাদের আল্লাহর সন্তুষ্টির জন্য খাওয়াই, আমরা তোমাদের থেকে কোনো প্রতিদান বা শুকরিয়া চাই না।"),
                TopicAyahRef(89, 15, "অতঃপর যখন তার রব তাকে পরীক্ষা করেন ও সম্মান দেন ও নিয়ামত দেন, সে বলে: আমার রব আমাকে সম্মান দিয়েছেন।"),
                TopicAyahRef(89, 16, "কিন্তু যখন তাকে পরীক্ষা করেন ও রিযিক সীমিত করেন, সে বলে: আমার রব আমাকে অসম্মান করেছেন।"),
                TopicAyahRef(93, 11, "তোমার রবের অনুগ্রহ ঘোষণা করো।"),
                TopicAyahRef(100, 11, "নিশ্চয় তাদের রব সেদিন তাদের কাছে সম্যক অবগত থাকবেন।"),
                TopicAyahRef(110, 3, "তোমার রবের প্রশংসা করো এবং তাঁর কাছে ক্ষমা চাও।")
            ),
            relatedTopics = listOf("sabr", "rida", "tawahhum", "tawakkul"),
