                TopicAyahRef(1, 1, "পরম করুণাময় অসীম দয়ালু আল্লাহর নামে।"),
                TopicAyahRef(2, 64, "তোমাদের মধ্যে যারা ঈমান এনেছে ও সৎকর্ম করেছে, তাদের কথা সত্য। তাদের জন্য রয়েছে ক্ষমা ও সম্মানজনক রিযিক।"),
                TopicAyahRef(2, 143, "এমনিভাবে আমি তোমাদেরকে মধ্যম সম্প্রদায় বানিয়েছি, যাতে তোমরা মানুষের উপর সাক্ষী হও। রাসূল তোমাদের উপর সাক্ষী হবেন।"),
                TopicAyahRef(2, 159, "যারা আল্লাহ নাজিল করেছেন সুস্পষ্ট প্রমাণ ও হেদায়েত গোপন করে, তাদের উপর আল্লাহ ও সমস্ত অভিশাপকারীর অভিশাপ।"),
                TopicAyahRef(2, 185, "রমজান মাসে কুরআন নাজিল হয়েছে মানুষের জন্য হেদায়েত স্বরূপ এবং সুস্পষ্ট প্রমাণ ও সত্য-মিথ্যার পার্থক্যকারী।"),
                TopicAyahRef(2, 218, "যারা ঈমান এনেছে এবং হিজরত করেছে আল্লাহর রাস্তায় জিহাদ করেছে, তারা আল্লাহর রহমত প্রত্যাশী। আল্লাহ ক্ষমাশীল, দয়ালু।"),
                TopicAyahRef(3, 8, "হে আমাদের রব! আমাদের হেদায়েত দেওয়ার পর আমাদের অন্তর বিচ্যুত করো না। তোমার পক্ষ থেকে রহমত দান করো।"),
                TopicAyahRef(3, 31, "বলুন: তোমরা আল্লাহকে ভালোবাসলে আমাকে অনুসরণ করো, আল্লাহ তোমাদের ভালোবাসবেন এবং তোমাদের গুনাহ মাফ করবেন।"),
                TopicAyahRef(3, 132, "আল্লাহ ও রাসূলের আনুগত্য করো, যাতে তোমরা রহমত লাভ করো।"),
                TopicAyahRef(3, 159, "আল্লাহর রহমতের কারণেই তুমি তাদের প্রতি নরম হলে। তুমি যদি রূঢ় ও কঠোর হতে, তবে তারা তোমার চারপাশ থেকে বিচ্ছিন্ন হয়ে যেতো।"),
                TopicAyahRef(4, 29, "হে ঈমানদারগণ! তোমরা একে অপরের সম্পদ অন্যায়ভাবে খাবে না। তবে পরস্পর সম্মতিতে ব্যবসা চলবে। নিজেদের নিজেদেরকে ধ্বংস করবে না।"),
                TopicAyahRef(4, 96, "তাদের জন্য রয়েছে আল্লাহর তরফ থেকে উচ্চ মর্যাদা, ক্ষমা ও বিশেষ রহমত। আল্লাহ ক্ষমাশীল, দয়ালু।"),
                TopicAyahRef(6, 12, "বলুন: আসমান ও পৃথিবীতে কার কর্তৃত্ব? বলুন: আল্লাহর। তিনি তাঁর নিজের উপর রহমত লিখে নিয়েছেন। তিনি তোমাদের কিয়ামতের দিন একত্রিত করবেন।"),
                TopicAyahRef(6, 54, "যারা ঈমান এনেছে ও সৎকর্ম করেছে, তাদের উপর কোনো ভয় নেই এবং তারা চিন্তিত হবে না।"),
                TopicAyahRef(6, 133, "তোমার রব অভাবমুক্ত, করুণাময়। তিনি চাইলে তোমাদের অপসারিত করে অন্য জাতির সৃষ্টি করতে পারেন।"),
                TopicAyahRef(7, 56, "পৃথিবীতে শান্তি স্থাপনের পর বিপর্যয় ছড়াবে না। আল্লাহর রহমত সৎকর্মশীলদের নিকটে।"),
                TopicAyahRef(7, 156, "তিনি বললেন: আমার শাস্তি যাকে ইচ্ছা দেবো। কিন্তু আমার রহমত সবকিছুকে পরিব্যাপ্ত করেছে।"),
                TopicAyahRef(7, 158, "বলুন: হে মানবকুল! আমি তোমাদের সবার প্রতি রাসূল, যাঁর রাজত্ব আসমান ও পৃথিবীর সবার উপর।"),
                TopicAyahRef(9, 21, "তাদের সুসংবাদ দাও জান্নাতের যেখানে নিচে নহর প্রবাহিত। সেখানে তারা চিরকাল থাকবে। আল্লাহর কাছে সেটি বড় সাফল্য।"),
                TopicAyahRef(10, 57, "হে মানবকুল! তোমাদের প্রতি তোমাদের রবের কাছ থেকে উপদেশ ও অন্তরে যা আছে তার জন্য নিরাময় এসেছে।"),
                TopicAyahRef(11, 9, "যদি আমি মানুষকে আমার রহমত স্বাদন করাই এবং তারপর তা তার কাছ থেকে সরিয়ে নিই, সে নিরাশ ও অকৃতজ্ঞ হয়।"),
                TopicAyahRef(11, 75, "ইব্রাহিম ছিলেন অত্যন্ত ক্ষমাশীল, নরম হৃদয় ও আল্লাহ অভিমুখী।"),
                TopicAyahRef(12, 53, "আমি নিজেকে দোষমুক্ত মনে করি না। নিশ্চয় নফস মন্দতার আদেশ দেয়, তবে আমার রব যাকে রহমত করেন তাকে ছাড়া। আমার রব ক্ষমাশীল, করুণাময়।"),
                TopicAyahRef(16, 18, "তোমরা আল্লাহর নিয়ামত গণনা করলে তা শেষ করতে পারবে না। আল্লাহ ক্ষমাশীল, করুণাময়।"),
                TopicAyahRef(17, 20, "প্রত্যেককে আমরা দিয়ে যাই — এদেরও আর ওদেরও — তোমাদের রবের দান। তোমাদের রবের দান সীমিত নয়।"),
                TopicAyahRef(18, 58, "তোমার রব ক্ষমাশীল, প্রভু। তিনি যদি তাদের অপরাধের কারণে পাকড়াও করতেন, তবে শাস্তি ত্বরান্বিত করতেন। কিন্তু তাদের জন্য একটি নির্ধারিত সময় আছে।"),
                TopicAyahRef(19, 2, "এটি তোমার রবের রহমতের স্মরণ — তাঁর বান্দা জাকারিয়ার প্রতি।"),
                TopicAyahRef(23, 109, "আমার বান্দাদের মধ্যে একদল ছিল যারা বলতো: হে আমাদের রব! আমরা ঈমান এনেছি। তুমি আমাদের ক্ষমা করো এবং আমাদের প্রতি রহমত করো।"),
                TopicAyahRef(23, 118, "তুমি বলো: হে আমার রব! ক্ষমা ও রহমত করো। তুমি রহমতকারীদের মধ্যে শ্রেষ্ঠ।"),
                TopicAyahRef(24, 10, "তোমাদের উপর আল্লাহর অনুগ্রহ ও রহমত না থাকলে এবং আল্লাহ তওবা গ্রহণকারী ও প্রজ্ঞাময় না হলে অবস্থা কঠিন হতো।"),
                TopicAyahRef(25, 30, "রাসূল বলবেন: হে আমার রব! আমার সম্প্রদায় এই কুরআনকে পরিত্যক্ত বস্তুরূপে গ্রহণ করেছে।"),
                TopicAyahRef(25, 50, "আমি এই কুরআনকে বিভক্ত করেছি যাতে তারা তা চিন্তা করে। কিন্তু তা মানুষের কাছে অপ্রিয়।"),
                TopicAyahRef(25, 63, "রহমানের বান্দা তারা যারা পৃথিবীতে বিনয়ের সাথে চলে এবং যখন অজ্ঞরা তাদের সম্বোধন করে, তারা বলে: সালাম।"),
                TopicAyahRef(25, 70, "তবে যে তওবা করে ঈমান আনে ও সৎকর্ম করে, তবে আল্লাহ তাদের গুনাহকে পুণ্যে পরিণত করবেন। আল্লাহ ক্ষমাশীল, দয়ালু।"),
                TopicAyahRef(27, 2, "এটি মুমিনদের জন্য হেদায়েত ও সুসংবাদ।"),
                TopicAyahRef(28, 86, "তুমি আশা করোনি যে তোমার রব তোমাকে কিতাব দেবেন। এটি তোমার রবের রহমত ছাড়া আর কিছুই নয়।"),
                TopicAyahRef(29, 21, "তিনি যাকে ইচ্ছা শাস্তি দেন এবং যাকে ইচ্ছা রহমত করেন। তাঁরই দিকে তোমরা ফিরে যাবে।"),
                TopicAyahRef(30, 33, "মানুষের উপর কোনো কষ্ট আসলে তারা তাদের রবের দিকে ফিরে আসে। কিন্তু তিনি যখন তাদের রহমত স্বাদন করান, তখন তাদের কিছু অংক শিরক করে।"),
                TopicAyahRef(30, 46, "তাঁর নিদর্শনের মধ্যে একটি হলো তিনি বায়ু প্রেরণ করেন সুসংবাদ বহনকারী হিসেবে। যাতে তিনি তোমাদের তাঁর রহমত আস্বাদন করান।"),
                TopicAyahRef(33, 43, "তিনিই তোমাদের প্রতি রহমত করেন এবং তাঁর ফেরেশতাগণ যাতে তোমরা অন্ধকার থেকে আলোতে বের হও। তিনি মুমিনদের প্রতি দয়ালু।"),
                TopicAyahRef(36, 43, "আমি যদি ইচ্ছা করি, তবে তাদের ডুবিয়ে দিতে পারি। তখন তাদের কোনো সাহায্যকারী থাকবে না।"),
                TopicAyahRef(40, 7, "ফেরেশতারা তাদের রবের প্রশংসা করে এবং মুমিনদের জন্য ক্ষমা প্রার্থনা করে। আল্লাহ তওবা গ্রহণকারী, করুণাময়।"),
                TopicAyahRef(42, 19, "আল্লাহ তাঁর বান্দাদের প্রতি অনুগ্রহশীল। তিনি যাকে ইচ্ছা রিযিক দেন। তিনিই পরাক্রমশালী, পরাক্রমশালী।"),
                TopicAyahRef(43, 32, "তারা কি তোমার রবের রহমত বণ্টন করে? আমি তাদের মধ্যে পার্থিব জীবনের রিযিক বণ্টন করেছি।"),
                TopicAyahRef(57, 9, "তিনিই তাঁর বান্দার উপর সুস্পষ্ট আয়াত নাজিল করেন যাতে তিনি তোমাদেরকে অন্ধকার থেকে আলোতে বের করেন। আল্লাহ তোমাদের প্রতি দয়ালু।"),
                TopicAyahRef(57, 21, "তোমাদের রবের ক্ষমা ও জান্নাতের দিকে প্রতিযোগিতা করো যা আকাশ ও পৃথিবীর প্রশস্ততার মতো।"),
                TopicAyahRef(57, 28, "তোমাদের প্রতি রহমত ও অনুগ্রহ দেবেন। আল্লাহ তাঁর অনুগ্রহে পরিপূর্ণ।"),
                TopicAyahRef(58, 12, "হে ঈমানদারগণ! তোমরা যখন রাসূলের সাথে একান্তে কথা বলতে চাও, তখন এই কথা বলার আগে দান করো। এটি তোমাদের জন্য উত্তম ও পবিত্রতার কারণ।"),
                TopicAyahRef(58, 22, "তুমি এমন কোনো সম্প্রদায় পাবে না যারা আল্লাহ ও শেষ দিনে ঈমান রাখে এবং আল্লাহ ও তাঁর রাসূলের বিরোধীদের সাথে বন্ধুত্ব করে।"),
                TopicAyahRef(76, 8, "তারা আল্লাহর ভালোবাসায় অভাবী, এতিম ও বন্দিকে খাওয়ায়।"),
                TopicAyahRef(85, 14, "তিনি ক্ষমাশীল, প্রেমময়।"),
                TopicAyahRef(85, 20, "অথচ আল্লাহ তাদের পেছন থেকে পরিবেষ্টন করে আছেন।"),
                TopicAyahRef(85, 21, "বরং এটি সম্মানিত কুরআন।"),
                TopicAyahRef(85, 22, "সুরক্ষিত ফলকে লিপিবদ্ধ।"),
                TopicAyahRef(89, 14, "নিশ্চয় তোমার রব পাহারায় আছেন।"),
                TopicAyahRef(95, 6, "তবে যারা ঈমান এনেছে ও সৎকর্ম করেছে, তাদের জন্য রয়েছে অব্যর্থ পুরস্কার।"),
                TopicAyahRef(97, 1, "নিশ্চয় আমি এটি নাজিল করেছি মর্যাদাপূর্ণ রাতে।"),
                TopicAyahRef(97, 3, "মর্যাদাপূর্ণ রাত হাজার মাসের চেয়ে উত্তম।"),
                TopicAyahRef(97, 4, "এতে ফেরেশতাগণ ও রূহ অবতরণ করে তাদের রবের অনুমতিক্রমে প্রতিটি কাজে।"),
                TopicAyahRef(97, 5, "শান্তি বিরাজমান এই রাতে ভোর পর্যন্ত।"),
                TopicAyahRef(100, 11, "নিশ্চয় তাদের রব সেদিন তাদের কাছে সম্যক অবগত থাকবেন।")
            ),
            relatedTopics = listOf("allahr-kshama", "tawba", "jannah", "istighfar"),
            relatedStories = listOf("ইব্রাহিম (আ.)", "মুহাম্মদ সা.", "ইউনুস (আ.)"),
