        ThematicTopic(
            slug = "taqwa",
            nameBn = "তাকওয়া",
            nameEn = "Taqwa",
            nameAr = "التقوى",
            domain = "ঈমান ও আকিদা",
            categoryBn = "মূল ধারণা",
            overviewBn = "তাকওয়া হলো আল্লাহকে ভয় করা এবং গুনাহ থেকে বেঁচে থাকা — শুধু ভয় নয়, বরং আল্লাহর ভালোবাসায় তাঁর আনুগত্ব করা। তাকওয়া কুরআনের মূল শর্ত এবং আল্লাহর নিকটে সবচেয়ে সম্মানিত ব্যক্তি হলো তাকওয়াশীল।",
            keyAyahs = listOf(
                TopicAyahRef(2, 2, "এই কিতাবে কোনো সন্দেহ নেই, এটি মুত্তাকীদের জন্য হেদায়েত।"),
                TopicAyahRef(3, 102, "হে ঈমানদারগণ! যেভাবে তাকওয়া অবলম্বন করা উচিত, সেভাবে আল্লাহকে ভয় করো। মুসলিম অবস্থায় মৃত্যুবরণ করো।"),
                TopicAyahRef(65, 2, "যে আল্লাহকে ভয় করে, তিনি তার জন্য বের হবার পথ করে দেন।")
            ),
            allAyahs = listOf(
                TopicAyahRef(2, 2, "এই কিতাবে কোনো সন্দেহ নেই, এটি মুত্তাকীদের জন্য হেদায়েত।"),
                TopicAyahRef(2, 3, "যারা গায়েবের উপর ঈমান আনে, নামাজ কায়েম করে এবং আমি তাদেরকে যা দিয়েছি তা থেকে ব্যয় করে।"),
                TopicAyahRef(2, 4, "এবং যারা তোমার উপর যা নাজিল হয়েছে এবং তোমার পূর্বে যা নাজিল হয়েছে তার উপর ঈমান আনে।"),
                TopicAyahRef(2, 5, "তারাই তাদের রবের পক্ষ থেকে হেদায়েতের উপর আছে এবং তারাই সফলকাম।"),
                TopicAyahRef(2, 21, "হে মানবকুল! তোমরা তোমাদের রবের ইবাদত করো যিনি তোমাদেরকে ও তোমাদের পূর্বপুরুষদের সৃষ্টি করেছেন।"),
                TopicAyahRef(2, 24, "যদি তোমরা এই কিতাব আনতে না পারো যা আমি আমার বান্দার উপর নাজিল করেছি, তবে আগুন থেকে রক্ষা পাওয়ার জন্য কাফের হওয়া থেকে বিরত থাকো।"),
                TopicAyahRef(2, 41, "তোমাদের কাছে যা আছে তা সত্যায়িত করে যা আমি নাজিল করেছি তাতে ঈমান আনো। প্রথম অস্বীকারকারী হয়ো না।"),
                TopicAyahRef(2, 63, "তোমরা যা দৃঢ়ভাবে ধরে রাখবে তা গ্রহণ করো এবং তাতে যা আছে মনে রাখো, যাতে তোমরা তাকওয়া অর্জন করো।"),
                TopicAyahRef(2, 74, "তারপর তোমাদের অন্তর শক্ত হয়ে গেল, পাথরের মতো বা তার চেয়েও শক্ত।"),
                TopicAyahRef(2, 124, "ইব্রাহিমকে তাঁর রব কয়েকটি বিষয়ে পরীক্ষা করেছিলেন, যা তিনি পূর্ণভাবে পালন করেছিলেন। তিনি বললেন: আমি তোমাকে মানুষের ইমাম বানাচ্ছি।"),
                TopicAyahRef(2, 132, "ইব্রাহিম তাঁর পুত্রগণকে এবং ইয়াকুব তাঁর পুত্রগণকে এই দ্বীনের জন্য অসিয়ত করেছিলেন।"),
                TopicAyahRef(2, 177, "পূর্ণ ঈমান শুধু মুখে নয়। ঈমান হলো আল্লাহ, ফেরেশতা, কিতাব, নবীদের প্রতি ঈমান এবং আত্মীয়, এতিম, দরিদ্র, মুসাফির, ভিক্ষুক ও দাসদের দান।"),
                TopicAyahRef(2, 189, "তোমাদের কাছে সম্পর্কে সৎবিচার করা হলো পবিত্র গৃহে প্রবেশ করা নয়, বরং সৎবিচার হলো তাকওয়া অবলম্বনকারী।"),
                TopicAyahRef(2, 197, "হজ নির্ধারিত কয়েক মাসে। যে হজ পালন করে তার উপর নারী সঙ্গ, অশ্লীলতা ও ঝগড়া নিষেধ। যা ভালো তা করো, আল্লাহ তাকওয়াশীলদের ভালোবাসেন।"),
                TopicAyahRef(2, 200, "মানুষের মধ্যে এমন কেউ আছে যে বলে: হে আমাদের রব! আমাদেরকে পৃথিবীতে দাও। তার আখিরাতে কোনো অংশ নেই।"),
                TopicAyahRef(3, 76, "বরং যে তাঁর অঙ্গীকার পূর্ণ করে ও তাকওয়া অবলম্বন করে, নিশ্চয় আল্লাহ মুত্তাকীদের ভালোবাসেন।"),
                TopicAyahRef(3, 102, "হে ঈমানদারগণ! যেভাবে তাকওয়া অবলম্বন করা উচিত সেভাবে আল্লাহকে ভয় করো। মুসলিম অবস্থায় মৃত্যুবরণ করো।"),
                TopicAyahRef(3, 130, "হে ঈমানদারগণ! সুদের চেয়ে দ্বিগুণ ও চৌগুণ বৃদ্ধি করো না। আল্লাহকে ভয় করো যাতে তোমরা সফল হও।"),
                TopicAyahRef(3, 133, "তোমরা তোমাদের রবের ক্ষমা ও জান্নাতের দিকে দৌড়াও যা আকাশ ও পৃথিবীর প্রশস্ততার মতো। মুত্তাকীদের জন্য প্রস্তুত।"),
                TopicAyahRef(3, 134, "যারা সুবিধা-অসুবিধায় দান করে, ক্রোধ সামলায়, মানুষকে ক্ষমা করে — আল্লাহ মুহসিনদের ভালোবাসেন।"),
                TopicAyahRef(3, 172, "যারা আঘাত পাওয়ার পরও আল্লাহ ও রাসূলের ডাকে সাড়া দিয়েছে, তাদের মধ্যে মুত্তাকীদের জন্য রয়েছে মহাপুরস্কার।"),
                TopicAyahRef(5, 2, "তোমরা পবিত্র গৃহে হজের সময় শিকারকে হারাম মনে করো না। আল্লাহর সীমালঙ্ঘন করো না। আল্লাহর প্রতি তোমাদের ভালোবাসা তোমাদের উপকারে আসুক।"),
                TopicAyahRef(5, 65, "যদি আহলে কিতাব ঈমান আনে ও তাকওয়া অবলম্বন করে, তবে আমি তাদের পাপ মোচন করবো এবং তাদেরকে সম্মানিত জান্নাতে প্রবেশ করাব।"),
                TopicAyahRef(5, 93, "যারা ঈমান এনেছে ও সৎকর্ম করেছে, তাদের উপর কোনো গুনাহ নেই যা তারা খেয়েছে, যদি তারা তাকওয়া অবলম্বন করে, ঈমান আনে ও সৎকর্ম করে।"),
                TopicAyahRef(7, 26, "হে আদম সন্তান! আমি তোমাদেরকে পোশাক দিয়েছি যা তোমাদের লজ্জাস্থান ঢাকে এবং পরিচ্ছদ হিসেবে — কিন্তু তাকওয়ার পোশাকই শ্রেষ্ঠ।"),
                TopicAyahRef(7, 35, "হে আদম সন্তান! তোমাদের মধ্য থেকে যদি আমার রাসূলগণ আসেন এবং তোমাদের কাছে আমার আয়াত বর্ণনা করেন, তবে যে তাকওয়া অবলম্বন করে ও সংশোধন করে তার কোনো ভয় নেই।"),
                TopicAyahRef(7, 128, "মূসা তাঁর সম্প্রদায়কে বললেন: আল্লাহর কাছে সাহায্য চাও এবং ধৈর্য ধরো। পৃথিবী আল্লাহর, তিনি যাকে ইচ্ছা তাঁর উত্তরাধিকারী করেন।"),
                TopicAyahRef(7, 156, "তিনি বললেন: আমার শাস্তি যাকে ইচ্ছা দেব। কিন্তু আমার রহমত সবকিছুকে পরিব্যাপ্ত করেছে। আমি তা লিখে দেবো যারা তাকওয়া অবলম্বন করে ও যাকাত দেয়।"),
                TopicAyahRef(8, 29, "হে ঈমানদারগণ! যদি তোমরা আল্লাহকে ভয় করো, তিনি তোমাদের জন্য পথ খুলে দেবেন এবং তোমাদের গুনাহ মাফ করবেন।"),
                TopicAyahRef(8, 69, "যুদ্ধে যা লাভ করেছ তা হালাল ও পবিত্র, কিন্তু তাকওয়া অবলম্বন করো। নিশ্চয় আল্লাহ ক্ষমাশীল, দয়ালু।"),
                TopicAyahRef(9, 109, "যে তার ভিত্তি আল্লাহর তাকওয়া ও সন্তুষ্টির উপর স্থাপন করে, সে কি শ্রেষ্ঠ নাকি যে ভিত্তি স্থাপন করে ধ্বংসপ্রাপ্ত খাড়ার কিনারায়?"),
                TopicAyahRef(16, 90, "আল্লাহ ন্যায়, ইনসাফ ও আত্মীয়দের দানের নির্দেশ দেন এবং অশ্লীল, খারাপ ও অত্যাচার থেকে নিষেধ করেন। তিনি তোমাদের উপদেশ দেন যাতে তোমরা শিক্ষা নাও।"),
                TopicAyahRef(20, 132, "তোমার পরিবারকে নামাজের নির্দেশ দাও এবং তাতে অটল থাকো। আমি তোমার কাছে রিযিক চাই না। আমি তোমাকে রিযিক দান করি। সৎ পরিণতি মুত্তাকীদের জন্য।"),
                TopicAyahRef(22, 37, "এগুলোর মাংস বা রক্ত আল্লাহর কাছে পৌঁছায় না, বরং তোমাদের তাকওয়াই তাঁর কাছে পৌঁছায়।"),
                TopicAyahRef(24, 52, "যে আল্লাহ ও তাঁর রাসূলের আনুগত্য করে, আল্লাহকে ভয় করে ও তাঁর তাকওয়া অবলম্বন করে, তারাই সফলকাম।"),
                TopicAyahRef(25, 63, "রহমানের বান্দা তারা যারা পৃথিবীতে বিনয়ের সাথে চলে এবং যখন অজ্ঞরা তাদের সম্বোধন করে, তারা বলে: সালাম।"),
                TopicAyahRef(25, 74, "এবং যারা বলে: হে আমাদের রব! আমাদের স্ত্রী ও সন্তানদের চোখের শীতলতা দান করো এবং আমাদের মুত্তাকীদের জন্য ইমাম বানাও।"),
                TopicAyahRef(28, 80, "যাদেরকে জ্ঞান দান করা হয়েছিল তারা বললো: আল্লাহর পুরস্কার তোমাদের সংগ্রহের চেয়ে উত্তম। যে তাকওয়া অবলম্বন করে তার জন্য তা উত্তম।"),
                TopicAyahRef(29, 69, "যারা আমাদের রাস্তায় সংগ্রাম করে তাদেরকে আমি অবশ্যই আমাদের রাস্তা দেখাবো। আল্লাহ মুহসিনদের সাথে আছেন।"),
                TopicAyahRef(31, 87, "যদি তোমাকে জিজ্ঞেস করে: কে আল্লাহকে ভয় করে? তবে বলো: যিনি নিজের উপর সীমাবদ্ধ নন এবং যিনি তাকওয়া অবলম্বন করেন।"),
                TopicAyahRef(38, 28, "আমরা কি ঈমানদার ও পাপীদের সমান গণ্য করবো?"),
                TopicAyahRef(39, 9, "যে সম্প্রদায় সিজদাকৃত ও দণ্ডায়মান অবস্থায় আল্লাহর ইবাদত করে, পরকালে আশা রাখে এবং রবের রহমত প্রত্যাশা করে — সে কি সমান যে জানে ও যে জানে না?"),
                TopicAyahRef(45, 18, "অতঃপর আমি তোমাকে সুনির্দিষ্ট বিধানের উপর প্রতিষ্ঠিত করেছি। সুতরাং তুমি তা অনুসরণ করো। অজ্ঞদের খেয়াল-খুশি অনুসরণ করো না।"),
                TopicAyahRef(47, 17, "যাদেরকে আল্লাহ হেদায়েত দিয়েছেন, তিনি তাদের তাকওয়া বৃদ্ধি করেন।"),
                TopicAyahRef(49, 13, "হে মানবকুল! আমি তোমাদের একজন পুরুষ ও একজন নারী থেকে সৃষ্টি করেছি এবং তোমাদের জাতি ও গোত্রে বিভক্ত করেছি। আল্লাহর কাছে সবচেয়ে সম্মানিত হলো তোমাদের মধ্যে তাকওয়াশীল।"),
                TopicAyahRef(50, 31, "জান্নাত তাকওয়াশীলদের কাছে নিকটে আনা হবে।"),
                TopicAyahRef(52, 32, "তাদের বুদ্ধি কি তাদের এই আদেশ দেয়, না তারা সীমালঙ্ঘনকারী সম্প্রদায়?"),
