                TopicAyahRef(21, 102, "তারা জাহান্নামের সামান্য শব্দও শুনবে না। তারা তাদের মন যা চায় তাতে বিলাসী থাকবে।"),
                TopicAyahRef(22, 14, "আল্লাহ যারা ঈমান এনেছে ও সৎকর্ম করেছে তাদের জান্নাতে প্রবেশ কাবেন যার নিচে নহর প্রবাহিত। আল্লাহ যা ইচ্ছা তা করেন।"),
                TopicAyahRef(22, 23, "যারা ঈমান এনেছে ও সৎকর্ম করেছে তাদের জান্নাতে প্রবেশ করানো হবে যার নিচে নহর প্রবাহিত। তাদের স্বর্ণ কড়া ও মুক্তা দিয়ে সজ্জিত করা হবে।"),
                TopicAyahRef(23, 11, "যারা তাদের আমানত ও প্রতিশ্রুতি রক্ষা করে, তারাই উত্তরাধিকারী হবে ফিরদাউস জান্নাতের — সেখানে তারা চিরকাল থাকবে।"),
                TopicAyahRef(25, 10, "বরকতময় তিনি, যিনি ইচ্ছা করলে তোমার জন্য জান্নাত থেকে উত্তম বানাতে পারেন — বাগান যার নিচে নহর প্রবাহিত।"),
                TopicAyahRef(25, 15, "বলো: এটা কি উত্তম না জাহান্নামের আগুন যা মুত্তাকীদের প্রতিশ্রুতি দেওয়া হয়েছে?"),
                TopicAyahRef(25, 16, "সেখানে তাদের জন্য রয়েছে যা তারা চায়, চিরস্থায়ী। এটা তোমার রবের ওয়াদা — যা চাওয়া হয়েছে।"),
                TopicAyahRef(29, 58, "যারা ঈমান এনেছে ও সৎকর্ম করেছে, আমি তাদের জান্নাতের উঁচু প্রকোষ্ঠে স্থান দেবো যার নিচে নহর প্রবাহিত।"),
                TopicAyahRef(29, 58, "যারা ঈমান এনেছে ও সৎকর্ম করেছে, আমি তাদের জান্নাতের উঁচু প্রকোষ্ঠে স্থান দেবো যার নিচে নহর প্রবাহিত। সেখানে তারা চিরকাল থাকবে। মুত্তাকীদের উত্তম প্রতিদান।"),
                TopicAyahRef(30, 15, "অতঃপর যারা ঈমান এনেছে ও সৎকর্ম করেছে, তারা জান্নাতে আনন্দিত থাকবে।"),
                TopicAyahRef(31, 8, "যারা ঈমান এনেছে ও সৎকর্ম করেছে — তাদের জন্য রয়েছে আল্লাহর অনুগ্রহের বাগান।"),
                TopicAyahRef(32, 19, "যারা ঈমান এনেছে ও সৎকর্ম করেছে, তাদের জন্য রয়েছে জান্নাত আতিথ্যের বাগান — তাদের আমলের প্রতিদান।"),
                TopicAyahRef(34, 4, "যাতে তিনি ঈমান এনেছে ও সৎকর্ম করেছে তাদের পুরস্কৃত করেন। তাদের জন্য ক্ষমা ও সম্মানজনক রিযিক।"),
                TopicAyahRef(35, 33, "চিরস্থায়ী জান্নাত যাতে তারা প্রবেশ করবে। তাদের স্বর্ণ কড়া ও মুক্তা দিয়ে সজ্জিত করা হবে।"),
                TopicAyahRef(35, 34, "যারা ঈমান এনেছে ও সৎকর্ম করেছে তাদেরকে জান্নাতে প্রবেশ করানো হবে। সেখানে তাদের জন্য রয়েছে চিরস্থায়ী নিয়ামত।"),
                TopicAyahRef(35, 35, "তারা বলবে: সম্মান আল্লাহর, যিনি আমাদের থেকে দুঃখ দূর করেছেন। নিশ্চয় আমাদের রব ক্ষমাশীল, কৃতজ্ঞতা স্বীকারকারী।"),
                TopicAyahRef(36, 55, "নিশ্চয় জান্নাতবাসীরা আজ আনন্দে মত্ত থাকবে।"),
                TopicAyahRef(36, 56, "তারা ও তাদের সঙ্গীরা ছায়ায় সিংহাসনে হেলান দিয়ে বসে আছে।"),
                TopicAyahRef(37, 40, "কেবল আল্লাহর শুদ্ধ বান্দারা নিরাপদ থাকবে।"),
                TopicAyahRef(37, 41, "তাদের জন্য রয়েছে নির্ধারিত রিযিক — ফলমূল। তারা সম্মানিত।"),
                TopicAyahRef(37, 42, "নিরাপদ বাগানে।"),
                TopicAyahRef(38, 49, "এটি একটি স্মরণ। আর মুত্তাকীদের জন্য উত্তম প্রত্যাবর্তন — সম্মানিত জান্নাত যার দরজা খোলা।"),
                TopicAyahRef(38, 50, "জান্নাত যার দরজা তাদের জন্য খোলা।"),
                TopicAyahRef(39, 20, "কিন্তু যারা তাদের রবকে ভয় করেছে, তাদের জন্য রয়েছে প্রশস্ত প্রকোষ্ঠ যার উপরে প্রকোষ্ঠ নির্মিত। যার নিচে নহর প্রবাহিত।"),
                TopicAyahRef(39, 61, "যারা তাকওয়া অবলম্বন করেছে, আল্লাহ তাদের তাদের মুক্তিস্থলে নিয়ে যাবেন। তাদের কোনো কষ্ট স্পর্শ করবে না এবং তারা চিন্তিত হবে না।"),
                TopicAyahRef(39, 73, "যারা তাদের রবকে ভয় করেছে তাদের দলে দলে জান্নাতের দিকে নিয়ে যাওয়া হবে। যতক্ষণ না তারা সেখানে পৌঁছে যায়, তার দরজা খোলা হয়।"),
                TopicAyahRef(40, 8, "হে আমাদের রব! মুমিন পুরুষ ও নারীদের জান্নাতে প্রবেশ কাও। যারা তোমার কাছে ইনসাফ করেছে তাদের সাথে।"),
                TopicAyahRef(40, 9, "তাদেরকে বিরত রাখো পাপ থেকে। যাকে তুমি পাপ থেকে বিরত রাখবে, সেদিন তার প্রতি রহমত করেছ। এটিই মহা সাফল্য।"),
                TopicAyahRef(41, 8, "যারা ঈমান এনেছে ও সৎকর্ম করেছে, তাদের জন্য অব্যর্থ পুরস্কার।"),
                TopicAyahRef(43, 70, "তোমরা ও তোমাদের স্ত্রীগণ আনন্দের সাথে জান্নাতে প্রবেশ করো।"),
                TopicAyahRef(43, 71, "তাদের পরিবেষ্টিত করা হবে স্বর্ণ থালা-বাসন ও পেয়ালায়। সেখানে তাদের মন যা চায় এবং চোখ যা আনন্দিত করে তা থাকবে।"),
                TopicAyahRef(43, 72, "এটি সেই জান্নাত যা তোমাদের আমলের কারণে তোমাদের প্রদান করা হয়েছে।"),
                TopicAyahRef(44, 51, "নিশ্চয় মুত্তাকীরা নিরাপদ স্থানে — জান্নাত ও প্রস্রবণে।"),
                TopicAyahRef(44, 52, "তারা উঠবে আসনের উপর মুখোমুখি।"),
                TopicAyahRef(44, 53, "তাদের পরিধানে থাকবে সবুজ রেশম ও চিকন বস্ত্র। রৌপ্য কড়া পরিধান করবে। তাদের রব পবিত্র পানীয় পান করাবেন।"),
                TopicAyahRef(44, 54, "এটি অবশ্যই হবে। আর তাদের সাথে বিয়ে দেবো বড় চোখের হূর।"),
                TopicAyahRef(45, 30, "যারা ঈমান এনেছে ও সৎকর্ম করেছে, তাদেরকে তাদের রব তাঁর রহমতে প্রবেশ কাবেন। এটিই স্পষ্ট সাফল্য।"),
                TopicAyahRef(46, 16, "এগুলো সেই ব্যক্তির পুরস্কার যার পূর্বপুরুষ মুসলিম ছিল। তাদের আমল থেকে আমি তাদের প্রতিদান দেবো।"),
                TopicAyahRef(47, 6, "তাদের জান্নাতে প্রবেশ কাবেন যা তিনি তাদের পরিচয় দিয়েছেন।"),
                TopicAyahRef(47, 12, "আল্লাহ যারা ঈমান এনেছে ও সৎকর্ম করেছে তাদের জান্নাতে প্রবেশ কাবেন যার নিচে নহর প্রবাহিত। আর যারা কুফরি করেছে, তারা ভোগ করে এবং পশুদের মতো খায়।"),
                TopicAyahRef(47, 15, "জান্নাতের দৃষ্টান্ত — প্রতিশ্রুত নহর পানি যা তৃষ্ণা নিবারণ করে না, দুধ যার স্বাদ অপরিবর্তিত, মদ যা পানকারীদের জন্য সুস্বাদু, এবং পরিশুদ্ধ মধু।"),
                TopicAyahRef(48, 5, "যাতে আল্লাহ মুমিন পুরুষ ও নারীদের জান্নাতে প্রবেশ কান যার নিচে নহর প্রবাহিত, সেখানে তারা চিরস্থায়ী হবে।"),
                TopicAyahRef(50, 31, "জান্নাত তাকওয়াশীলদের কাছে নিকটে আনা হবে।"),
                TopicAyahRef(50, 32, "এটিই তোমাদের প্রতিশ্রুতি — প্রত্যেক তওবাকারী ও হিফাজতকারীর জন্য।"),
                TopicAyahRef(50, 35, "তাদের জন্য সেখানে যা চায় তা আছে এবং আমার কাছে আরও বেশি আছে।"),
                TopicAyahRef(51, 15, "নিশ্চয় মুত্তাকীরা বাগান ও প্রস্রবণে থাকবে।"),
                TopicAyahRef(51, 16, "যা তাদের রব তাদের দিয়েছেন তা গ্রহণ করবে। তারা এর আগে সৎকর্মশীল ছিল।"),
                TopicAyahRef(52, 17, "নিশ্চয় মুত্তাকীরা বাগান ও সমৃদ্ধিতে থাকবে।"),
                TopicAyahRef(52, 18, "তারা তাদের রব তাদের দিয়েছেন তা ভোগ করছে। তাদের রব তাদেরকে জাহান্নামের শাস্তি থেকে রক্ষা করেছেন।"),
                TopicAyahRef(52, 19, "তোমাদের আমলের কারণে আনন্দের সাথে খাও ও পান করো।"),
                TopicAyahRef(52, 20, "তারা সারিবদ্ধভাবে সিংহাসনে হেলান দিয়ে বসে আছে। আমি তাদের সাথে বিয়ে দেবো বড় চোখের হূর।"),
                TopicAyahRef(55, 46, "কিন্তু যে তার রবের মহত্ত্বকে ভয় করে, তার জন্য দুটি জান্নাত।"),
                TopicAyahRef(55, 47, "তোমরা কোন্ নিয়ামতকে অস্বীকার করবে তোমাদের রবের?"),
                TopicAyahRef(55, 48, "দুটিতেই রয়েছে বিভিন্ন রঙের ফলমূল।"),
                TopicAyahRef(55, 50, "তাদের মধ্যে প্রবাহিত দুটি প্রস্রবণ।"),
                TopicAyahRef(55, 54, "তারা হেলান দিয়ে বসবে যার আস্তরণ মোটা রেশম। দুটি জান্নাতের ফল নাগালের মধ্যে।"),
                TopicAyahRef(55, 62, "এই দুটির বাইরে আরও দুটি জান্নাত রয়েছে।"),
                TopicAyahRef(55, 64, "গাঢ় সবুজ রঙের।"),
                TopicAyahRef(55, 65, "তোমরা কোন্ নিয়ামতকে অস্বীকার করবে তোমাদের রবের?"),
                TopicAyahRef(55, 66, "তাদের মধ্যে দুটি প্রস্রবণ উচ্ছ্বসিত।"),
                TopicAyahRef(55, 68, "তাদের মধ্যে ফলমূল, খেজুর ও ডালিম।"),
                TopicAyahRef(56, 12, "নিশ্চয় ডান দিকের দল জান্নাতে থাকবে।"),
                TopicAyahRef(56, 13, "প্রথম দল প্রথম জান্নাতে।"),
                TopicAyahRef(56, 15, "স্বর্ণ খচিত আসনে হেলান দিয়ে বসবে।"),
                TopicAyahRef(56, 17, "চিরকুমার বালক তাদের পরিবেষ্টিত করবে।"),
                TopicAyahRef(56, 18, "স্ফটিক পাত্র, পেয়ালা ও স্বর্ণ পানপাত্র নিয়ে ঘুরবে। তারা পান করবে যা মাথা ব্যথা করে না বা নেশাগ্রস্ত করে না।"),
                TopicAyahRef(56, 22, "বড় চোখের হূর, যাদের চোখ কেবল তাদের জন্য।"),
                TopicAyahRef(56, 30, "এবং প্রশস্ত ছায়া।"),
                TopicAyahRef(56, 32, "এবং প্রচুর ফল।"),
                TopicAyahRef(56, 33, "যা শেষ হবে না বা নিষিদ্ধ হবে না।"),
                TopicAyahRef(56, 34, "এবং উঁচু আসন।"),
                TopicAyahRef(56, 35, "আমি বিশেষ সৃষ্টিতে নারী সৃজন করবো।"),
                TopicAyahRef(56, 88, "যদি সে নিকটবর্তীদের অন্তর্ভুক্ত হয়।"),
                TopicAyahRef(57, 12, "যেদিন তুমি দেখবে মুমিন পুরুষ ও নারীদের আলো তাদের সামনে ও ডানে দ্রুত ছুটছে।"),
                TopicAyahRef(57, 15, "সুতরাং আজ কোনো বন্দী বিনিময় গ্রহণ করা হবে না, কাফেরদের থেকে বা তাদের থেকে কোনো সুপারিশ গৃহীত হবে না। তাদের আবাস আগুন।"),
