    /** Get a topic by slug */
    fun getTopic(slug: String): ThematicTopic? = topics.find { it.slug == slug }

    /** Search topics by Bangla / English / Arabic name */
    fun search(query: String): List<ThematicTopic> {
        if (query.isBlank()) return topics
        val q = query.trim().lowercase()
        return topics.filter {
            it.nameBn.contains(query) || it.nameEn.lowercase().contains(q) ||
                it.nameAr.contains(query) || it.domain.contains(query) ||
                it.categoryBn.contains(query)
        }
    }

    /** Get topics by domain */
    fun byDomain(domain: String): List<ThematicTopic> =
        topics.filter { it.domain == domain }

    /** All domains */
    fun domains(): List<String> = topics.map { it.domain }.distinct()

    /** Get topic with resolved ayah text — returns just metadata */
    fun getTopicOverview(slug: String): ThematicTopic? = getTopic(slug)
}
